queries.sql:
SELECT label AS person, no_longer_listed, source
FROM nodes
WHERE type = 'Person' AND no_longer_listed = 1;

SELECT verb, inverse, pt_verb, pt_inverse, origin
FROM verbs
ORDER BY verb;

SELECT publisher, kind, published, substr(sha256, 1, 12) AS sha256_prefix, bytes
FROM coverage
ORDER BY published IS NULL, published, publisher;

SELECT s.title, j.value AS source_id
FROM stories s, json_each(s.stands_on) j
ORDER BY s.published, s.title, source_id;
